<script setup>
import Updates from './Updates.vue';
import Overview from './Overview.vue';
import LimitStatus from './LimitStatus.vue';
import QuickActions from './QuickActions.vue';
import MobileMonitor from './MobileMonitor.vue';
import TrafficSummary from './TrafficSummary.vue';
import Logs from './Logs.vue';
import SiteIcon from './SiteIcon.vue';
import IconPicker from './IconPicker.vue';
import { pageSizes, validPageSize } from './format.mjs';
import appMeta from '../package.json';
import { ref, computed, onMounted, onUnmounted, watch, nextTick } from 'vue';
import { Anchor, LayoutDashboard, Files, Waves, SlidersHorizontal, Server, ScrollText, Settings, ArrowDown, ArrowUp, Plus, RefreshCw, ChevronRight, ArrowUpRight, MoreHorizontal, Search, X, Check, CircleHelp, Wifi, WifiOff, ShieldCheck, FlaskConical, Play, Pause, LogOut, Pencil, Trash2, Clock3, Eye, Download, Tag, Zap, AlertTriangle, CheckCircle2, Menu, CheckCheck, Link2, LockKeyhole, Layers3, Activity, Sun, Moon, GripVertical, ChevronUp, ChevronDown } from 'lucide-vue-next';

const M=1048576;
const theme=ref(localStorage.getItem('harbor-theme')||'dark');
watch(theme,value=>{document.documentElement.dataset.theme=value;localStorage.setItem('harbor-theme',value);},{immediate:true});
function toggleTheme(){theme.value=theme.value==='dark'?'light':'dark';}
const compact=ref(window.innerWidth<=760), filtersOpen=ref(false);
function resized(){compact.value=window.innerWidth<=760;}
const page=ref('overview'), mobileNav=ref(false), auth=ref(null), pass=ref(''), authBusy=ref(false), authError=ref('');
const data=ref(null), toast=ref(null), loading=ref(false), modal=ref(null), form=ref({}), saving=ref(false), modalError=ref(''), preview=ref(null), selected=ref([]);
const query=ref(''), stateFilter=ref(''), clientFilter=ref(''), hostFilter=ref(''), poolFilter=ref(''), tagFilter=ref(''), listPage=ref(1);
let timer, toastTimer, lastFocus, searchTimer, listSequence=0, loadingSummary=false, restoringRoute=false, metadataPending=false;
const workspace=ref(null), catalog=ref({tags:[],hosts:[]}), listing=ref({rows:[],total:0,pages:1}), detail=ref(null), listError=ref(''), listLoading=ref(false), summaryError=ref('');
const sort=ref('name'), sortOrder=ref('asc');
const mobileTabs=[{id:'overview',label:'总览',icon:LayoutDashboard},{id:'torrents',label:'种子',icon:Files},{id:'pools',label:'站点',icon:Waves},{id:'activity',label:'记录',icon:ScrollText}];
watch(modal, async (value, previous)=>{if(value&&!previous)lastFocus=document.activeElement;await nextTick();if(value)document.querySelector('.modal input:not([disabled]), .modal select, .modal button')?.focus();else if(previous)lastFocus?.focus();});
function modalKeys(e){const root=modal.value?'.modal':filtersOpen.value?'.filter-open':mobileNav.value?'.sidebar.open':null;if(!root)return;if(e.key==='Escape'&&!saving.value){if(modal.value)modal.value=null;else if(filtersOpen.value)filtersOpen.value=false;else mobileNav.value=false;return;}if(e.key==='Tab'){const nodes=[...document.querySelectorAll(`${root} button:not([disabled]),${root} input:not([disabled]),${root} select:not([disabled]),${root} a[href]`)].filter(n=>n.offsetParent!==null),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}
watch([modal,mobileNav,filtersOpen],async([m,n,f])=>{document.body.style.overflow=m||n||f?'hidden':'';await nextTick();if(n)document.querySelector('.sidebar nav button')?.focus();else if(f)document.querySelector('.filter-open select')?.focus();});

const nav=[{id:'overview',label:'传输总览',icon:LayoutDashboard},{id:'torrents',label:'所有种子',icon:Files},{id:'pools',label:'带宽池',icon:Waves},{id:'quick',label:'一键操作',icon:Zap},{id:'rules',label:'自动化规则',icon:SlidersHorizontal},{id:'clients',label:'下载器',icon:Server},{id:'activity',label:'运行记录',icon:ScrollText},{id:'updates',label:'版本更新',icon:Download}];
const title=computed(()=>[...nav,{id:'settings',label:'设置'}].find(n=>n.id===page.value)?.label || '总览');
const torrents=computed(()=>data.value?.torrents||[]), clients=computed(()=>data.value?.clients||[]), plans=computed(()=>data.value?.plan||[]), pools=computed(()=>data.value?.pools||[]), rules=computed(()=>data.value?.rules||[]);
const demo=computed(()=>data.value?.settings.mode==='demo'), controlled=computed(()=>data.value?.settings.controlEnabled);
const up=computed(()=>clients.value.reduce((s,c)=>s+c.upload,0)), down=computed(()=>clients.value.reduce((s,c)=>s+c.download,0));
const active=computed(()=>data.value?.active||0);
const online=computed(()=>clients.value.filter(c=>c.online).length);
const allTags=computed(()=>catalog.value.tags);
const allHosts=computed(()=>catalog.value.hosts);
const pageSize=ref(validPageSize(localStorage.getItem('harbor-page-size')));
const pageCount=computed(()=>listing.value.pages);
const visible=computed(()=>listing.value.rows);
watch(pageSize,value=>{localStorage.setItem('harbor-page-size',String(value));listPage.value=1;});
function listParams(){return new URLSearchParams({q:query.value,state:stateFilter.value,client:clientFilter.value,host:hostFilter.value,pool:poolFilter.value,tag:tagFilter.value,page:String(listPage.value),pageSize:String(pageSize.value),sort:sort.value,order:sortOrder.value});}
const filterCount=computed(()=>[stateFilter,clientFilter,hostFilter,poolFilter,tagFilter].filter(v=>v.value).length);
function clearFilters(){query.value='';stateFilter.value='';clientFilter.value='';hostFilter.value='';poolFilter.value='';tagFilter.value='';listPage.value=1;}
function syncRows(){if(!data.value)return;const rows=[...listing.value.rows,...data.value.topTorrents,...(detail.value?[detail.value.torrent]:[])];data.value.torrents=rows;data.value.plan=rows.map(t=>t.plan).filter(Boolean);data.value.managed=detail.value?.managed||[];}
async function loadList(){if(!auth.value?.authenticated||page.value!=='torrents')return;const id=++listSequence;listLoading.value=true;try{const result=await api('torrents?'+listParams());if(id===listSequence){listing.value=result;listPage.value=result.page;listError.value='';syncRows();}}catch(e){if(id===listSequence)listError.value=e.message;}finally{if(id===listSequence)listLoading.value=false;}}
watch([query,stateFilter,clientFilter,hostFilter,poolFilter,tagFilter,sort,sortOrder],()=>{if(restoringRoute)return;listPage.value=1;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{writeRoute();loadList();},250);});
watch([listPage,pageSize],()=>{if(restoringRoute)return;writeRoute();loadList();});
function writeRoute(){if(!auth.value?.authenticated)return;const p=page.value==='torrents'?listParams():new URLSearchParams();if(modal.value?.kind==='explain')p.set('task',modal.value.key);window.history.replaceState(window.history.state,'','#'+page.value+(p.size?'?'+p:''));}
async function readRoute(){restoringRoute=true;const [route,search='']=location.hash.slice(1).split('?');if([...nav,{id:'settings'}].some(n=>n.id===route))page.value=route;const p=new URLSearchParams(search);if(route==='torrents'){query.value=p.get('q')||'';stateFilter.value=p.get('state')||'';clientFilter.value=p.get('client')||'';hostFilter.value=p.get('host')||'';poolFilter.value=p.get('pool')||'';tagFilter.value=p.get('tag')||'';sort.value=['name','upload','download','progress','updated'].includes(p.get('sort'))?p.get('sort'):'name';sortOrder.value=p.get('order')==='desc'?'desc':'asc';pageSize.value=validPageSize(p.get('pageSize')||pageSize.value);listPage.value=Math.max(1,Number(p.get('page'))||1);}await nextTick();restoringRoute=false;if(auth.value?.authenticated)loadList();const task=p.get('task');if(task&&auth.value?.authenticated)explain({key:task},false);else if(modal.value?.kind==='explain')modal.value=null;}
watch(modal,(v,old)=>{document.body.style.overflow=v?'hidden':'';if(!v&&old?.kind==='explain'&&new URLSearchParams(location.hash.split('?')[1]).has('task')){if(history.state?.harborDetail)history.back();else writeRoute();}});
const activityTab=ref('logs'),orderSaving=ref(false),dragId=ref(''),dropId=ref('');
const orderedRules=computed(()=>[...rules.value].sort((a,b)=>a.priority-b.priority||a.id.localeCompare(b.id)));
async function moveRule(id,to){if(orderSaving.value)return;const ids=orderedRules.value.map(r=>r.id),from=ids.indexOf(id);if(from<0||to<0||to>=ids.length||from===to)return;ids.splice(from,1);ids.splice(to,0,id);orderSaving.value=true;try{await api('rules/order','PUT',{ids,revision:data.value.ruleRevision});await load();notify('规则顺序已保存，越靠上主池优先级越高');}catch(e){notify(e.message,true);await load();}finally{orderSaving.value=false;}}
function startDrag(e,id){if(orderSaving.value){e.preventDefault();return;}dragId.value=id;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',id);}
function dropRule(e,id){e.preventDefault();const source=dragId.value;dragId.value='';dropId.value='';if(!source||source===id)return;const index=orderedRules.value.findIndex(r=>r.id===id);moveRule(source,index);}
let pointerStart=null;
function pointerStartRule(e,id){if(orderSaving.value||e.button!==0)return;pointerStart={id,x:e.clientX,y:e.clientY};e.currentTarget.setPointerCapture(e.pointerId);}
function pointerMoveRule(e){if(!pointerStart)return;if(!dragId.value&&Math.hypot(e.clientX-pointerStart.x,e.clientY-pointerStart.y)<6)return;dragId.value=pointerStart.id;dropId.value=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-rule-id]')?.dataset.ruleId||'';}
function pointerEndRule(e){if(!pointerStart)return;const source=pointerStart.id,target=dropId.value;pointerStart=null;e.currentTarget.releasePointerCapture(e.pointerId);dragId.value='';dropId.value='';if(target&&target!==source)moveRule(source,orderedRules.value.findIndex(r=>r.id===target));}
function pointerCancelRule(){pointerStart=null;dragId.value='';dropId.value='';}
const topTorrents=computed(()=>data.value?.topTorrents||[]);
const events=computed(()=>data.value?.events||[]);
const blockedPlans=computed(()=>data.value?.blocked?[{execution:data.value.blocked}]:[]);
const conflicts=computed(()=>data.value?.conflictCount?[{count:data.value.conflictCount}]:[]);
const explanation=computed(()=>modal.value?.kind==='explain'?detail.value?.torrent:null);
const states={downloading:'下载中',seeding:'做种中',paused:'已暂停',stalled:'等待连接',checking:'校验中',error:'异常'};
const format=(v,unit=true)=>{if(v==null)return unit?'不限速':'—';if(!Number.isFinite(Number(v)))return '—';if(v<1024)return `${Math.round(v)}${unit?' B/s':''}`;if(v>=1024*M)return `${(v/(1024*M)).toFixed(1)}${unit?' GiB/s':''}`;if(v<M)return `${(v/1024).toFixed(v<10240?1:0)}${unit?' KiB/s':''}`;return `${(v/M).toFixed(1)}${unit?' MiB/s':''}`;};
const bytes=v=>v>=1024**3?`${(v/1024**3).toFixed(1)} GiB`:`${(v/M).toFixed(1)} MiB`;
const time=(v,short=false)=>v?new Intl.DateTimeFormat('zh-CN',{timeZone:data.value?.settings.timezone||'Asia/Shanghai',hour:'2-digit',minute:'2-digit',...(short?{}:{second:'2-digit'}),hourCycle:'h23'}).format(new Date(v)):'—';
const date=computed(()=>new Intl.DateTimeFormat('zh-CN',{timeZone:data.value?.settings.timezone||'Asia/Shanghai',month:'long',day:'numeric',weekday:'long'}).format(new Date()));
const planMap=computed(()=>new Map(plans.value.map(p=>[p.key,p])));
const plan=key=>planMap.value.get(key);
const busyPools=computed(()=>[...pools.value].sort((a,b)=>(poolStats(b.id).upload+poolStats(b.id).download)-(poolStats(a.id).upload+poolStats(a.id).download)).slice(0,3));
function poolStats(id){return data.value?.poolStats?.[id]||{count:0,upload:0,download:0,allocated:0};}
function notify(message,error=false){toast.value={message,error};clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value=null,5500);}
async function api(path,method='GET',body,attempt=0){const response=await fetch(`/api/${path}`,{method,headers:body!==undefined?{'Content-Type':'application/json'}:{},...(body!==undefined?{body:JSON.stringify(body)}:{})});const value=await response.json();if(!response.ok){if(response.status===401&&path!=='auth/login'){auth.value={setup:false,authenticated:false};data.value=null;}if(response.status===409&&value.error?.startsWith('正在同步')&&attempt<5){await new Promise(r=>setTimeout(r,700));return api(path,method,body,attempt+1);}throw new Error(value.error||'请求失败');}return value;}
async function load(metadata=true){if(!auth.value?.authenticated)return;if(loadingSummary){metadataPending=metadataPending||metadata;return;}loadingSummary=true;try{const [summary,meta]=await Promise.all([api('summary'),metadata||!workspace.value?api('workspace'):Promise.resolve(workspace.value)]);workspace.value=meta;const old=data.value;if(old&&old.settings.mode!==summary.settings.mode){listing.value={rows:[],total:0,pages:1};detail.value=null;selected.value=[];listPage.value=1;}data.value={...summary,...meta,torrents:[],plan:[],managed:detail.value?.managed||[],events:old?.events||[]};summaryError.value='';syncRows();if(page.value==='torrents'){await loadList();if(metadata)catalog.value=await api('catalog');}if(page.value==='activity')data.value.events=await api('events');if(modal.value?.kind==='explain'){detail.value=await api('torrents/'+encodeURIComponent(modal.value.key));syncRows();}}catch(e){if(auth.value?.authenticated){summaryError.value=e.message;notify(e.message,true);}}finally{loadingSummary=false;if(metadataPending){metadataPending=false;void load(true);}}}
async function bootstrap(){authError.value='';try{auth.value=await api('auth/status');if(auth.value.authenticated){await load();readRoute();}}catch(e){authError.value=e.message;}}
function visibleLoad(){if(!document.hidden)load(false);}
async function login(){authBusy.value=true;authError.value='';try{await api(auth.value.setup?'auth/setup':'auth/login','POST',{password:pass.value});auth.value={setup:false,authenticated:true};pass.value='';await load();}catch(e){authError.value=e.message;}finally{authBusy.value=false;}}
async function logout(){try{await api('auth/logout','POST',{});auth.value={setup:false,authenticated:false};data.value=null;}catch(e){notify(e.message,true);}}
function viewPool(id){clearFilters();poolFilter.value=id;navigate('torrents');}
function navigate(id){if(page.value!==id){history.pushState({},'','#'+id);page.value=id;nextTick(()=>window.scrollTo(0,0));}mobileNav.value=false;selected.value=[];}
watch(page,async()=>{if(!data.value)return;filtersOpen.value=false;if(page.value==='torrents'){await loadList();catalog.value=await api('catalog');}if(page.value==='activity')data.value.events=await api('events');if(['rules','clients','settings','pools'].includes(page.value)){workspace.value=await api('workspace');Object.assign(data.value,workspace.value);}});
async function refresh(){loading.value=true;try{await api('refresh','POST',{});await load(false);notify('传输状态已更新');}catch(e){notify(e.message,true);}finally{loading.value=false;}}
async function patchSettings(patch){try{await api('settings','PUT',patch);await load();notify('运行设置已保存');}catch(e){notify(e.message,true);}}
function switchMode(){modal.value={kind:'mode'};modalError.value='';}
async function toggleControl(){if(!controlled.value){modal.value={kind:'control'};modalError.value='';}else await patchSettings({controlEnabled:false});}
async function release(){saving.value=true;modalError.value='';try{const result=await api('release','POST',{});await load();notify(result.remaining?`已停止接管，${result.remaining} 项因失联或外部修改保留，请查看任务详情`:'已释放接管，恢复接管前设置',!!result.remaining);modal.value=null;}catch(e){modalError.value=e.message;}finally{saving.value=false;}}
async function open(kind,item){let labelTorrent;if(kind==='labels'&&selected.value.length===1){const key=selected.value[0];try{labelTorrent=(await api('torrents/'+encodeURIComponent(key))).torrent;if(selected.value.length!==1||selected.value[0]!==key)return;}catch(e){notify(e.message,true);return;}}preview.value=null;modalError.value='';modal.value={kind,id:item?.id};
  if(kind==='client')form.value={name:item?.name||'',type:item?.type||'qb',url:item?.url||'',username:item?.username||'',password:'',enabled:item?.enabled??true,hasPassword:item?.hasPassword};
  if(kind==='pool')form.value={name:item?.name||'',upload:item?.upload==null?'':item.upload/M,download:item?.download==null?'':item.download/M,weight:item?.weight||1,color:item?.color||'#218575',icon:item?.icon??'auto'};
  if(kind==='rule')form.value={name:item?.name||'',enabled:item?.enabled??true,priority:item?.priority??50,clients:[...(item?.clients||[])],hosts:(item?.hosts||[]).join(', '),tags:(item?.tags||[]).join(', '),category:item?.category||'',states:[...(item?.states||[])],poolId:item?.poolId||'',upload:item?.upload==null?'':item.upload/M,download:item?.download==null?'':item.download/M,weight:item?.weight||1,scheduled:!!item?.schedule,start:item?.schedule?.start||'08:00',end:item?.schedule?.end||'23:00',days:[...(item?.schedule?.days||[])]};
  if(kind==='labels')form.value={tags:selected.value.length===1?(labelTorrent?.localTags||[]).join(', '):''};
  if(kind==='override')form.value={upload:'',download:'',weight:3,minutes:30};
}
const split=v=>String(v||'').split(/[,，\n]/).map(s=>s.trim()).filter(Boolean);
const limitInput=v=>v===''||v==null?null:Number(v)*M;
function rulePayload(){const f=form.value;return {...f,hosts:split(f.hosts),tags:split(f.tags),upload:limitInput(f.upload),download:limitInput(f.download),priority:Number(f.priority),weight:Number(f.weight),schedule:f.scheduled?{start:f.start,end:f.end,days:f.days}:null};}
async function previewRule(){saving.value=true;modalError.value='';try{preview.value=await api('preview','POST',{...rulePayload(),id:modal.value.id});}catch(e){modalError.value=e.message;}finally{saving.value=false;}}
async function testClient(){saving.value=true;modalError.value='';try{const result=await api('clients/test','POST',{...form.value,id:modal.value.id});preview.value={connection:`连接成功 · ${result.version} · ${result.torrents} 个种子`};}catch(e){modalError.value=e.message;}finally{saving.value=false;}}
async function saveModal(){saving.value=true;modalError.value='';try{const {kind,id}=modal.value;const f=form.value;
  if(kind==='client')await api(`clients${id?'/'+id:''}`,id?'PUT':'POST',f);
  if(kind==='pool')await api(`pools${id?'/'+id:''}`,id?'PUT':'POST',{...f,upload:limitInput(f.upload),download:limitInput(f.download),weight:Number(f.weight)});
  if(kind==='rule')await api(`rules${id?'/'+id:''}`,id?'PUT':'POST',rulePayload());
  if(kind==='labels')await api('labels','PUT',{keys:selected.value,tags:split(f.tags)});
  if(kind==='override')await api('override','POST',{...f,keys:selected.value,upload:limitInput(f.upload),download:limitInput(f.download),weight:Number(f.weight),minutes:Number(f.minutes)});
  if(kind==='control')await api('settings','PUT',{controlEnabled:true});
  if(kind==='mode')await api('settings','PUT',{mode:demo.value?'real':'demo'});
  if(kind==='delete')await api(`${modal.value.collection}/${id}`,'DELETE');
  if(kind==='settings')await api('settings','PUT',{...f,uploadBudget:limitInput(f.uploadBudget),downloadBudget:limitInput(f.downloadBudget),pollSeconds:Number(f.pollSeconds),controlSeconds:Number(f.controlSeconds)});
  if(kind==='password')await api('auth/password','POST',f);
  modal.value=null;selected.value=[];await load();notify('已保存');
}catch(e){modalError.value=e.message;}finally{saving.value=false;}}
function editSettings(){modal.value={kind:'settings'};modalError.value='';const s=data.value.settings;form.value={uploadBudget:s.uploadBudget==null?'':s.uploadBudget/M,downloadBudget:s.downloadBudget==null?'':s.downloadBudget/M,pollSeconds:s.pollSeconds,controlSeconds:s.controlSeconds,timezone:s.timezone,demandAware:s.demandAware??true};}
function confirmDelete(collection,item){modal.value={kind:'delete',collection,id:item.id,name:item.name};modalError.value='';}
async function toggleRule(r){try{await api(`rules/${r.id}`,'PUT',{...r,enabled:!r.enabled});await load();notify(r.enabled?'规则已停用':'规则已启用');}catch(e){notify(e.message,true);}}
async function explain(t,push=true){try{detail.value=await api('torrents/'+encodeURIComponent(t.key));syncRows();modal.value={kind:'explain',key:t.key};modalError.value='';if(push){const p=new URLSearchParams(location.hash.split('?')[1]||'');p.set('task',t.key);history.pushState({harborDetail:true},'','#'+page.value+'?'+p);}}catch(e){notify(e.message,true);}}
async function reclaim(key){saving.value=true;try{await api('reclaim','POST',{key});await load();notify('已重新接管，下一轮按规则调整');}catch(e){modalError.value=e.message;}finally{saving.value=false;}}
async function clearOverride(key){try{await api('override','POST',{keys:[key],clear:true});await load();notify('临时设置已取消');}catch(e){notify(e.message,true);}}
async function exportConfig(){try{const config=await api('export');const url=URL.createObjectURL(new Blob([JSON.stringify(config,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`torrent-harbor-config-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(url);notify('配置已导出，不含密码；完整备份请保存 data 目录');}catch(e){notify(e.message,true);}}
function selectAll(){selected.value=visible.value.every(t=>selected.value.includes(t.key))?selected.value.filter(k=>!visible.value.some(t=>t.key===k)):[...new Set([...selected.value,...visible.value.map(t=>t.key)])];}
const modalTitle=computed(()=>({client:modal.value?.id?'编辑下载器':'连接一个下载器',pool:modal.value?.id?'编辑带宽池':'创建带宽池',rule:modal.value?.id?'编辑自动化规则':'创建自动化规则',labels:'设置本地标签',override:'临时调整带宽',explain:'限速解释',mode:'切换运行环境',control:'开启自动接管',release:'释放接管并恢复',delete:'删除配置',settings:'带宽与调度设置',password:'修改管理密码'}[modal.value?.kind]||''));
onMounted(async()=>{readRoute();window.addEventListener('resize',resized);window.addEventListener('hashchange',readRoute);window.addEventListener('popstate',readRoute);document.addEventListener('visibilitychange',visibleLoad);window.addEventListener('keydown',modalKeys);await bootstrap();timer=setInterval(visibleLoad,5000);});
onUnmounted(()=>{document.body.style.overflow='';window.removeEventListener('resize',resized);window.removeEventListener('hashchange',readRoute);window.removeEventListener('popstate',readRoute);document.removeEventListener('visibilitychange',visibleLoad);clearTimeout(searchTimer);window.removeEventListener('keydown',modalKeys);clearInterval(timer);clearTimeout(toastTimer);});
</script>

<template>
  <div v-if="!auth || (auth.authenticated&&!data)" class="initial"><Anchor :size="34"/><p>{{summaryError||authError||'正在读取传输状态…'}}</p><button v-if="summaryError||authError" class="btn" @click="auth?.authenticated?load():bootstrap()">重试</button></div>
  <div v-else-if="!auth.authenticated" class="auth-shell">
    <form class="auth-card" @submit.prevent="login"><div class="brand"><Anchor :size="27"/><span>种子港<small>Torrent Harbor</small></span></div><h1>{{auth.setup?'设置管理密码':'登录种子港'}}</h1><p>{{auth.setup?'创建密码后连接你的下载器。':'查看传输状态，管理带宽分配。'}}</p><label>管理密码<input v-model="pass" type="password" :autocomplete="auth.setup?'new-password':'current-password'" required :minlength="auth.setup?10:undefined" maxlength="256" autofocus></label><p v-if="authError" class="form-error" role="alert">{{authError}}</p><button class="btn primary" :disabled="authBusy">{{authBusy?'正在验证…':auth.setup?'创建并进入':'登录'}}</button><small>v{{appMeta.version}} · 数据保存在你的 NAS</small></form>
  </div>
  <div v-else class="app-shell">
    <div v-if="mobileNav" class="nav-backdrop" @click="mobileNav=false"></div>
    <aside class="sidebar" :class="{open:mobileNav}">
      <a class="brand" href="#" @click.prevent="navigate('overview')"><span class="brand-symbol"><Anchor :size="25"/></span><span>种子港<small>Torrent Harbor</small></span></a>
      <div class="workspace-label">工作空间</div>
      <nav><button v-for="n in nav" :key="n.id" :aria-label="n.label" :title="n.label" :class="{active:page===n.id}" @click="navigate(n.id)"><component :is="n.icon" :size="19"/><span>{{n.label}}</span><span v-if="n.id==='torrents'" class="nav-count">{{data.total}}</span><span v-if="n.id==='rules'" class="nav-dot"></span></button></nav>
      <div class="sidebar-bottom"><div class="harbor-status"><span class="status-beacon"></span><div>{{controlled?'自动调度运行中':'只读预览运行中'}}<small>{{demo?'演示数据 · 与真实环境隔离':'真实环境 · 本地运行'}}</small></div><Activity :size="17"/></div><button class="settings-nav" aria-label="设置与备份" title="设置与备份" :class="{active:page==='settings'}" @click="navigate('settings')"><Settings :size="19"/><span>设置与备份</span><ChevronRight :size="16"/></button><div class="sidebar-footer"><span>TORRENT HARBOR</span><span>v{{data.version||appMeta.version}}</span></div></div>
    </aside>
    <div class="main-shell">
      <header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" aria-label="更多页面" @click="mobileNav=true"><Menu :size="21"/></button><b class="mobile-brand">种子港</b><span class="desktop-only">{{title}}</span></div><div class="top-actions"><span class="mode-pill" :class="{real:!demo}">{{demo?'演示环境':controlled?'自动接管中':'只读预览'}}</span><button class="icon-button" @click="refresh" :disabled="loading" aria-label="刷新传输状态"><RefreshCw :size="18" :class="{spin:loading}"/></button><button class="icon-button" @click="toggleTheme" :aria-label="theme==='dark'?'切换浅色主题':'切换深色主题'"><Sun v-if="theme==='dark'" :size="18"/><Moon v-else :size="18"/></button><button class="icon-button desktop-only" @click="navigate('settings')" aria-label="打开设置"><Settings :size="18"/></button></div></header>
      <main>
        <div class="page-heading" :class="{'overview-heading':page==='overview'}"><div><h1>{{page==='overview'?'实时总览':compact&&page==='pools'?'站点带宽':title}}</h1><p v-if="page==='overview'">{{date}}<span class="desktop-only"> · 后台持续同步</span></p><p v-else-if="page==='torrents'">{{data.total.toLocaleString()}} 个种子 · {{active}} 个正在传输</p><p v-else-if="compact">查看当前状态，复杂编辑请使用电脑。</p></div><div v-if="!compact" class="heading-actions"><button v-if="!compact&&page==='pools'" class="btn primary" @click="open('pool')"><Plus :size="16"/>新建带宽池</button><button v-if="!compact&&page==='rules'" class="btn primary" @click="open('rule')"><Plus :size="16"/>新建规则</button><button v-if="!compact&&page==='clients'" class="btn primary" @click="open('client')"><Plus :size="16"/>连接下载器</button></div></div>
        <p v-if="summaryError" class="error-message" role="alert">同步失败：{{summaryError}}。当前显示上次读取的数据。<button class="text-button" @click="load(false)">重试</button></p>
        <div v-if="demo" class="environment-banner"><span class="banner-icon"><FlaskConical :size="16"/></span><span>你正在探索演示工作空间。<span class="banner-sub">下载器、站点及速率均为模拟数据。</span></span><button v-if="!compact" @click="switchMode">连接我的下载器<ArrowUpRight :size="14"/></button></div>
        <LimitStatus v-if="page!=='overview'" :status="data.limitStatus" @inspect="navigate('activity')"/><div v-if="page!=='overview'&&data.error" class="warning-banner"><AlertTriangle :size="17"/><span>{{data.error}}</span></div>

        <div v-if="page!=='overview'&&controlled&&blockedPlans.length" class="warning-banner"><AlertTriangle :size="18"/><span>{{blockedPlans[0].execution}}</span></div>
        <Overview v-if="page==='overview'" :data="data" :rules="rules" :api="api" :format="format" :time="time" @navigate="navigate" @pool="viewPool" @detail="explain" @changed="load(false)" @notify="notify"/>
        <QuickActions v-if="page==='quick'" :api="api" :data="data" :mobile="compact" @changed="load(false)" @notify="notify"/>
        <MobileMonitor v-if="compact&&['pools','rules','clients','settings','updates'].includes(page)" :key="page" :page="page" :data="data" :rules="rules" :format="format" :time="time" :theme="theme" @theme="toggleTheme" @logout="logout" @members="viewPool"/>
        <template v-if="page==='torrents'">
          <div class="mobile-filter-toolbar"><div class="search-field"><Search :size="17"/><input v-model="query" placeholder="搜索种子、标签、站点" aria-label="手机搜索种子"></div><button class="btn" @click="filtersOpen=!filtersOpen" :aria-expanded="filtersOpen"><SlidersHorizontal :size="17"/>筛选<span v-if="filterCount">{{filterCount}}</span></button></div><div class="filter-bar" :role="compact&&filtersOpen?'dialog':undefined" :aria-modal="compact&&filtersOpen?true:undefined" :aria-label="compact&&filtersOpen?'筛选种子':undefined" :class="{'filter-open':filtersOpen}"><div class="mobile-filter-heading"><h2>筛选种子</h2><button class="icon-button" @click="filtersOpen=false" aria-label="收起筛选"><X :size="20"/></button></div><div class="search-field"><Search :size="17"/><input v-model="query" @input="listPage=1" placeholder="搜索名称、站点、标签…" aria-label="搜索种子"></div><select v-model="clientFilter" @change="listPage=1" aria-label="筛选下载器"><option value="">所有下载器</option><option v-for="c in clients" :value="c.id">{{c.name}}</option></select><select v-model="stateFilter" @change="listPage=1" aria-label="筛选状态"><option value="">所有状态</option><option value="offline">下载器离线</option><option v-for="(v,k) in states" :value="k">{{v}}</option></select><select v-model="hostFilter" @change="listPage=1" aria-label="筛选 Tracker"><option value="">所有 Tracker</option><option v-for="h in allHosts">{{h}}</option></select><select v-model="tagFilter" @change="listPage=1" aria-label="筛选标签"><option value="">所有标签</option><option v-for="t in allTags">{{t}}</option></select><select v-model="poolFilter" @change="listPage=1" aria-label="筛选带宽池"><option value="">所有带宽池</option><option v-for="p in pools" :value="p.id">{{p.name}}</option></select><select v-model="sort" aria-label="种子排序"><option value="name">名称</option><option value="download">下载速率</option><option value="upload">上传速率</option><option value="progress">进度</option></select><select v-model="sortOrder" aria-label="排序方向"><option value="asc">升序</option><option value="desc">降序</option></select><button class="text-button" @click="clearFilters">清空筛选</button><button class="btn mobile-apply" @click="filtersOpen=false">查看结果</button></div><p v-if="listError" class="error-message" role="alert">{{listError}} <button class="text-button" @click="loadList">重试</button></p>
          <div v-if="selected.length&&!compact" class="selection-bar"><span><CheckCheck :size="17"/>已选择 {{selected.length}} 个任务</span><button class="btn" @click="open('labels')"><Tag :size="14"/>本地标签</button><button class="btn" @click="open('override')"><Zap :size="14"/>临时调整</button><button class="text-button" @click="selected=[]">取消选择</button></div>
          <section class="panel task-list-panel" :aria-busy="listLoading"><div class="mobile-task-list"><button v-for="t in visible" :key="t.key" class="mobile-task" @click="explain(t)"><strong>{{t.name}}</strong><span>{{t.clientName}} · {{t.online?states[t.state]:'下载器离线'}} · {{(t.progress*100).toFixed(1)}}%</span><span class="mobile-task-bottom"><span>{{t.plan?.poolName||'未分组'}}</span><span>{{t.online?'↓ '+format(t.download)+' · ↑ '+format(t.upload):'上次同步 '+time(t.updated)}}</span></span></button><p v-if="!visible.length" class="empty-message">{{listLoading?'正在加载…':'没有符合条件的种子'}}</p></div><div class="table-scroll desktop-task-table"><table class="torrent-table full"><thead><tr><th><input type="checkbox" :checked="visible.length>0&&visible.every(t=>selected.includes(t.key))" @change="selectAll" aria-label="选择本页种子"></th><th>种子名称 / 进度</th><th>下载器 / Tracker</th><th>状态</th><th>下载 / 上传</th><th>目标限速 ↓ / ↑</th><th>主带宽池</th><th></th></tr></thead><tbody><tr v-for="t in visible" :key="t.key"><td><input type="checkbox" v-model="selected" :value="t.key" :aria-label="'选择 '+t.name"></td><td class="name-cell"><button class="name-link" @click="explain(t)">{{t.name}}</button><div class="progress-line"><i :style="{width:t.progress*100+'%'}"></i></div><small class="secondary">{{(t.progress*100).toFixed(1)}}% · {{bytes(t.size)}} <span v-for="tag in t.tags" class="tiny-tag" :class="{local:t.localTags.includes(tag)}">{{tag}}</span></small></td><td>{{t.clientName}}<small class="secondary block">{{t.hosts.join(', ')||'等待完整 Tracker'}}</small></td><td><span class="state-pill" :class="t.online?t.state:'error'">{{t.online?states[t.state]:'已失联'}}</span></td><td><span class="rate-blue block">↓ {{format(t.download)}}</span><span class="rate-green block">↑ {{format(t.upload)}}</span></td><td><span class="block">{{plan(t.key)?.managed?format(plan(t.key).download):'不接管'}}</span><span class="block secondary">{{plan(t.key)?.managed?format(plan(t.key).upload):'不接管'}}</span></td><td><span class="pool-tag">{{plan(t.key)?.managed?plan(t.key).poolName:'未分组'}}</span><small class="block secondary">{{plan(t.key)?.override?'临时设置有效':''}}</small></td><td><button class="icon-button" aria-label="查看限速解释" @click="explain(t)"><CircleHelp :size="17"/></button></td></tr><tr v-if="!visible.length"><td colspan="8" class="empty-table"><Files :size="28"/><p>没有找到符合条件的种子</p><span>尝试调整筛选，或连接一个下载器。</span></td></tr></tbody></table></div><div class="pagination"><span>共 {{listing.total}} 个任务 <label class="page-size-label">每页 <select v-model.number="pageSize" aria-label="每页种子数量"><option v-for="size in pageSizes" :key="size" :value="size">{{size}}</option></select> 个</label></span><div><button class="btn small" :disabled="listPage===1" @click="listPage--">上一页</button><span>{{listPage}} / {{pageCount}}</span><button class="btn small" :disabled="listPage>=pageCount" @click="listPage++">下一页</button></div></div></section>
          <p class="page-note desktop-only"><CircleHelp :size="14"/>目标限速为规则计算结果。开启接管后才会写入；点击任务可查看下载器回读值。本地标签只保存在种子港。</p>
        </template>

        <template v-if="!compact&&page==='pools'"><div class="pool-card-grid"><article class="panel pool-detail" v-for="p in pools"><div class="pool-detail-top"><SiteIcon :pool="p" :rules="rules" :size="42"/><div><h2>{{p.name}}</h2><p>{{poolStats(p.id).count}} 个任务 · 权重 {{p.weight}}</p></div><button class="icon-button" aria-label="编辑带宽池" @click="open('pool',p)"><Pencil :size="16"/></button></div><div class="pool-direction" v-for="dir in ['upload','download']"><div><span><ArrowUp v-if="dir==='upload'" :size="14"/><ArrowDown v-else :size="14"/>{{dir==='upload'?'上传':'下载'}}</span><strong>{{format(poolStats(p.id)[dir])}}</strong></div><div class="pool-meter"><span :style="{width:Math.min(100,p[dir]?poolStats(p.id)[dir]/p[dir]*100:0)+'%',background:p.color}"></span></div><small>共享硬上限 {{format(p[dir])}}</small></div><div class="pool-detail-bottom"><button class="text-button" @click="viewPool(p.id)">查看成员<ChevronRight :size="14"/></button><button class="icon-button danger-text" aria-label="删除带宽池" @click="confirmDelete('pools',p)"><Trash2 :size="15"/></button></div></article><button class="empty-card add-pool" @click="open('pool')"><Plus :size="26"/><strong>新的带宽安排</strong><span>创建共享池，再通过规则加入成员</span></button></div><div class="info-panel"><ShieldCheck :size="21"/><div><strong>共享的是整组预算，不是给每个种子重复设置同样的上限。</strong><p>同池成员可以跨 QB / TR。全局预算先分给各池，再按任务权重分配。首版采用硬上限，池内闲余按权重重新分配，不跨池突破上限。多个池命中时，仅最高优先级的主池参与共享记账。</p></div></div></template>

        <template v-if="!compact&&page==='rules'"><div class="rule-summary"><span><span class="dot green-dot"></span>{{rules.filter(r=>r.enabled).length}} 条规则启用</span><span>拖动把手调整顺序，越靠上主池优先级越高</span><span>标签条件全部满足 · Tracker 条件任一满足</span></div><section class="panel rule-list"><article v-for="(r,index) in orderedRules" :key="r.id" :data-rule-id="r.id" class="rule-item" :class="{'rule-dragging':dragId===r.id,'rule-drop-target':dropId===r.id}" @dragover.prevent="dropId=r.id" @drop="dropRule($event,r.id)" @dragend="dragId='';dropId=''"><div class="rule-reorder"><button class="icon-button drag-handle" :draggable="false" @pointerdown="pointerStartRule($event,r.id)" @pointermove="pointerMoveRule" @pointerup="pointerEndRule" @pointercancel="pointerCancelRule" :disabled="orderSaving" :aria-label="'拖动排列规则 '+r.name" @dragstart="startDrag($event,r.id)"><GripVertical :size="19"/></button><div><button class="icon-button" :disabled="orderSaving||index===0" :aria-label="'上移规则 '+r.name" @click="moveRule(r.id,index-1)"><ChevronUp :size="14"/></button><button class="icon-button" :disabled="orderSaving||index===orderedRules.length-1" :aria-label="'下移规则 '+r.name" @click="moveRule(r.id,index+1)"><ChevronDown :size="14"/></button></div></div><div class="rule-priority">{{String(r.priority).padStart(2,'0')}}</div><div class="rule-content"><div class="rule-title"><h3>{{r.name}}</h3><span v-if="r.schedule" class="tiny-tag"><Clock3 :size="11"/>{{r.schedule.start}}–{{r.schedule.end}}</span></div><div class="rule-conditions"><span v-if="r.hosts.length"><Link2 :size="12"/>{{r.hosts.join(' / ')}}</span><span v-if="r.tags.length"><Tag :size="12"/>{{r.tags.join(' + ')}}</span><span v-if="r.clients.length"><Server :size="12"/>{{r.clients.map(id=>data.configuredClients.find(c=>c.id===id)?.name||id).join(' / ')}}</span><span v-if="!r.hosts.length&&!r.tags.length&&!r.clients.length">所有任务</span><span v-if="r.states.length">{{r.states.map(s=>states[s]).join(' / ')}}</span></div><div class="rule-effects"><span v-if="r.poolId"><Waves :size="12"/>{{pools.find(p=>p.id===r.poolId)?.name}}</span><span v-if="r.upload!=null">单种上传 ≤ {{format(r.upload)}}</span><span v-if="r.download!=null">单种下载 ≤ {{format(r.download)}}</span><span v-if="r.weight>1">任务权重 ×{{r.weight}}</span><small>命中 {{data.ruleCounts[r.id]||0}} 个任务</small></div></div><div class="rule-actions"><button class="toggle" :class="{on:r.enabled}" @click="toggleRule(r)" :aria-label="(r.enabled?'停用':'启用')+r.name" :aria-pressed="r.enabled"><i></i></button><button class="icon-button" aria-label="编辑规则" @click="open('rule',r)"><Pencil :size="16"/></button><button class="icon-button danger-text" aria-label="删除规则" @click="confirmDelete('rules',r)"><Trash2 :size="16"/></button></div></article><div v-if="!rules.length" class="empty-table">创建第一条规则，让带宽自动分配。</div></section><div class="info-panel"><Eye :size="22"/><div><strong>先看影响，再让规则运行。</strong><p>编辑规则时可以预览命中的种子和目标限速。附加单种上限取所有命中规则中更严格的值；临时提权也遵守这些上限。时间段按 {{data.settings.timezone}} 执行，跨午夜归属于开始日。</p></div></div></template>

        <template v-if="!compact&&page==='clients'"><div class="client-management"><article class="panel client-manage-card" v-for="c in data.configuredClients.filter(c=>Boolean(c.demo)===demo)"><div class="client-top"><span class="client-logo" :class="c.type">{{c.type==='qb'?'qB':'Tr'}}</span><div><h3>{{c.name}}</h3><p>{{c.type==='qb'?'qBittorrent':'Transmission'}} · {{c.demo?'模拟连接':c.url}}</p></div><span class="state-pill" :class="clients.find(x=>x.id===c.id)?.online?'seeding':'error'">{{clients.find(x=>x.id===c.id)?.online?'已连接':c.enabled?'未连接':'已停用'}}</span></div><div class="native-info"><div><span>原生上传上限</span><strong>{{format(clients.find(x=>x.id===c.id)?.native?.upload)}}</strong></div><div><span>原生下载上限</span><strong>{{format(clients.find(x=>x.id===c.id)?.native?.download)}}</strong></div><div><span>替代限速模式</span><strong>{{clients.find(x=>x.id===c.id)?.native?.alternative?'已开启':'未开启'}}</strong></div></div><p class="client-error" v-if="clients.find(x=>x.id===c.id)?.error">{{clients.find(x=>x.id===c.id).error}}</p><div class="client-footer"><span>{{c.demo?'演示连接不会访问网络':c.hasPassword?'连接密码已加密保存':'未保存连接密码'}}</span><div v-if="!c.demo"><button class="text-button" @click="open('client',c)">编辑连接</button><button class="icon-button danger-text" aria-label="移除下载器" @click="confirmDelete('clients',c)"><Trash2 :size="15"/></button></div></div></article><button class="empty-card" @click="open('client')"><Plus :size="26"/><strong>添加下载器</strong><span>连接本地 NAS 或远程服务器上的 QB / TR</span></button></div><div v-if="demo&&data.configuredClients.some(c=>!c.demo)" class="info-panel"><Server :size="22"/><div><strong>真实下载器配置已保存。</strong><p>切换到真实环境后会开始只读同步，演示任务与真实任务分开显示。</p></div></div></template>

        <template v-if="page==='activity'"><div class="activity-tabs range-tabs"><button :class="{active:activityTab==='logs'}" :aria-pressed="activityTab==='logs'" @click="activityTab='logs'">诊断日志</button><button :class="{active:activityTab==='events'}" :aria-pressed="activityTab==='events'" @click="activityTab='events'">活动记录</button></div><Logs v-if="activityTab==='logs'" :api="api" :notify="notify" :clients="data.configuredClients" :timezone="data.settings.timezone"/><template v-else><section class="panel activity-list"><article v-for="e in events" :key="e.id"><span class="event-icon" :class="e.level"><CheckCircle2 v-if="e.level==='success'" :size="18"/><AlertTriangle v-else-if="['warning','error'].includes(e.level)" :size="18"/><Activity v-else :size="18"/></span><div><h3>{{e.title}}</h3><p>{{e.detail}}</p></div><time>{{time(e.time)}}<small>{{new Date(e.time).toLocaleDateString('zh-CN',{timeZone:data.settings.timezone})}}</small></time></article></section><p class="page-note">保留最近 2,000 条记录，界面展示最近 150 条。速率采样保留 7 天。</p></template></template>

        <Updates v-if="!compact&&page==='updates'" :api="api" :notify="notify" :controlled="controlled" :managed="data.managedCount"/>
        <template v-if="!compact&&page==='settings'"><div class="settings-grid"><section class="panel settings-panel"><div class="panel-head"><div><h2>外观主题</h2><p>右上角太阳／月亮按钮也可以快速切换。</p></div></div><div class="setting-row"><div><strong>当前主题</strong><p>选择保存在当前浏览器中。</p></div><select v-model="theme" aria-label="外观主题"><option value="dark">深色</option><option value="light">浅色</option></select></div></section><section class="panel settings-panel"><div class="panel-head"><div><h2>运行与接管</h2><p>你决定什么时候将计划变成动作。</p></div><ShieldCheck :size="21"/></div><div class="setting-row"><div><strong>运行环境</strong><p>{{demo?'独立演示数据，不连接真实下载器':'真实下载器，仅连接已启用的配置'}}</p></div><button class="btn" @click="switchMode">{{demo?'切换真实环境':'切换演示环境'}}</button></div><div class="setting-row"><div><strong>自动限速接管</strong><p>{{controlled?'后台持续执行规则，关闭网页后继续运行':'仅计算目标值，不写入下载器'}}</p></div><button class="toggle" :class="{on:controlled}" @click="toggleControl" aria-label="自动限速接管" :aria-pressed="controlled"><i></i></button></div><div class="setting-row"><div><strong>释放接管并恢复</strong><p>仅恢复仍等于本程序写入值的设置，保留外部修改。</p></div><button class="btn" @click="modal={kind:'release'};modalError=''">释放接管</button></div><div class="setting-foot"><AlertTriangle :size="15"/>暂停接管或停止程序后，下载器保留最后的限速值。需要恢复时请使用“释放接管”。</div></section><section class="panel settings-panel"><div class="panel-head"><div><h2>带宽与调度</h2><p>上传、下载分别安排，预算仅覆盖受管任务。</p></div><Waves :size="21"/></div><div class="setting-metrics"><div><span>受管上传总预算</span><strong>{{format(data.settings.uploadBudget)}}</strong></div><div><span>受管下载总预算</span><strong>{{format(data.settings.downloadBudget)}}</strong></div><div><span>状态同步</span><strong>{{data.settings.pollSeconds}} 秒</strong></div><div><span>限额调度</span><strong>{{data.settings.controlSeconds}} 秒</strong></div></div><div class="setting-row"><div><strong>计划时区</strong><p>{{data.settings.timezone}}</p></div><button class="btn" @click="editSettings">编辑设置</button></div><div class="setting-foot">跨多条宽带时，请按出口分别部署实例。原生总限速、分组与局域网设置仍会影响实际效果。</div></section><section class="panel settings-panel"><div class="panel-head"><div><h2>配置与备份</h2><p>你的规则与连接，留在自己的设备上。</p></div><Download :size="21"/></div><div class="setting-row"><div><strong>导出配置</strong><p>导出下载器地址、池与规则，不含密码和恢复基线。</p></div><button class="btn" @click="exportConfig">导出 JSON</button></div><div class="setting-row"><div><strong>完整备份</strong><p>停止服务后，备份整个 data 目录，包括数据库与 secret.key。</p></div><span class="tiny-tag">本地持久化</span></div></section><section class="panel settings-panel"><div class="panel-head"><div><h2>管理访问</h2><p>保护你的下载器连接与管理操作。</p></div><LockKeyhole :size="21"/></div><div class="setting-row"><div><strong>管理密码</strong><p>会话在服务重启后失效。</p></div><button class="btn" @click="modal={kind:'password'};form={current:'',password:''};modalError=''">修改密码</button></div><div class="setting-row"><div><strong>退出工作空间</strong><p>后台调度继续运行。</p></div><button class="btn" @click="logout"><LogOut :size="14"/>退出登录</button></div></section></div></template>
        <footer class="main-footer"><span>种子港 v{{data.version}}</span><span>{{demo?'演示环境':'真实环境'}} · {{data.syncing?'正在同步':`读取于 ${time(data.now)}`}}</span></footer>
      </main>
    </div>

    <nav class="mobile-tabbar" aria-label="手机主导航"><button v-for="n in mobileTabs" :key="n.id" :class="{active:page===n.id}" :aria-current="page===n.id?'page':undefined" @click="navigate(n.id)"><component :is="n.icon" :size="20"/><span>{{n.label}}</span></button></nav>
    <div v-if="modal" class="modal-backdrop" @click.self="!saving&&(modal=null)"><section class="modal" :class="{'modal-wide':['rule','explain'].includes(modal.kind)}" role="dialog" aria-modal="true" :aria-label="modalTitle"><div class="modal-head"><div><h2>{{modalTitle}}</h2></div><button class="icon-button" aria-label="关闭对话框" :disabled="saving" @click="modal=null"><X :size="21"/></button></div><form @submit.prevent="saveModal">
      <div class="modal-body">
        <template v-if="modal.kind==='client'"><p class="form-intro">通过官方 WebUI / RPC 接口连接。测试连接与保存配置均不会修改限速。</p><label>连接名称<input v-model="form.name" placeholder="例如：NAS 主力下载器" required maxlength="100"></label><div class="form-two"><label>下载器类型<select v-model="form.type"><option value="qb">qBittorrent</option><option value="tr">Transmission</option></select></label><label>连接状态<select v-model="form.enabled"><option :value="true">启用</option><option :value="false">停用</option></select></label></div><label>服务地址<input v-model="form.url" type="url" :placeholder="form.type==='qb'?'http://192.168.1.10:8080':'http://192.168.1.10:9091'" required></label><small class="field-note">{{form.type==='qb'?'填写 WebUI 根地址，支持反向代理子路径。':'填写根地址或完整的 /transmission/rpc 地址。'}}</small><div class="form-two"><label>用户名<input v-model="form.username" autocomplete="off" placeholder="可留空"></label><label>密码<input v-model="form.password" type="password" autocomplete="new-password" :placeholder="form.hasPassword?'留空保留已保存密码':'连接密码'"></label></div><div class="form-callout"><LockKeyhole :size="16"/>连接密码使用持久化密钥加密保存，不会返回前端。</div><div v-if="preview?.connection" class="preview-success"><CheckCircle2 :size="17"/>{{preview.connection}}</div></template>
        <template v-if="modal.kind==='pool'"><IconPicker v-model="form.icon" :name="form.name" :id="modal.id" :rules="rules"/><label>带宽池名称<input v-model="form.name" required maxlength="100" placeholder="例如：A 站 · 日常下载"></label><div class="form-two"><label>共享上传上限 · MiB/s<input v-model="form.upload" type="number" min="0.001" step="any" placeholder="留空不设池上限"></label><label>共享下载上限 · MiB/s<input v-model="form.download" type="number" min="0.001" step="any" placeholder="留空不设池上限"></label></div><div class="form-two"><label>全局分配权重<input v-model="form.weight" type="number" min="1" max="100" required></label><label>标识颜色<input v-model="form.color" type="color"></label></div><div class="form-callout"><Waves :size="17"/>创建后，通过规则把 Tracker 或标签对应的任务加入池。池上限是硬上限，全局预算不足时按池权重分配。</div></template>
        <template v-if="modal.kind==='rule'"><div class="form-two"><label>规则名称<input v-model="form.name" required maxlength="100" placeholder="例如：A 站保种任务"></label><label>主池优先级 · 越小越优先<input v-model="form.priority" type="number" min="0" max="9999" required></label></div><div class="form-section-title">选择哪些种子<small>不同条件之间同时满足；留空表示不限</small></div><label>Tracker 主机名<input v-model="form.hosts" placeholder="tracker.example.org, *.example.net"></label><small class="field-note">多个主机名任一命中；使用完整 Tracker 列表，不包含路径或 passkey。</small><div class="form-two"><label>标签 · 多个标签需全部满足<input v-model="form.tags" placeholder="保种, 电影"></label><label>QB 分类<input v-model="form.category" placeholder="可留空，只读匹配"></label></div><fieldset class="field-group"><legend>下载器范围</legend><div class="checkbox-group"><label v-for="c in data.configuredClients" class="check-label"><input type="checkbox" v-model="form.clients" :value="c.id">{{c.name}}<small>{{c.demo?'演示':'真实'}}</small></label></div></fieldset><fieldset class="field-group"><legend>任务状态</legend><div class="checkbox-group"><label v-for="(v,k) in states" class="check-label"><input type="checkbox" v-model="form.states" :value="k">{{v}}</label></div></fieldset><div class="form-section-title">怎样安排带宽</div><label>加入主带宽池<select v-model="form.poolId"><option value="">不指定池 · 只应用单种限制 / 权重</option><option v-for="p in pools" :value="p.id">{{p.name}}</option></select></label><div class="form-two"><label>单种上传上限 · MiB/s<input v-model="form.upload" type="number" min="0.001" step="any" placeholder="留空不增加单种上限"></label><label>单种下载上限 · MiB/s<input v-model="form.download" type="number" min="0.001" step="any" placeholder="留空不增加单种上限"></label></div><div class="form-two"><label>任务分配权重<input v-model="form.weight" type="number" min="1" max="100" required></label><label>规则状态<select v-model="form.enabled"><option :value="true">启用</option><option :value="false">停用</option></select></label></div><div class="form-section-title">什么时候生效</div><label class="check-label"><input type="checkbox" v-model="form.scheduled">只在指定时间段生效 <small>{{data.settings.timezone}}</small></label><template v-if="form.scheduled"><div class="form-two"><label>开始时间<input v-model="form.start" type="time" required></label><label>结束时间<input v-model="form.end" type="time" required></label></div><div class="checkbox-group"><label v-for="(v,k) in ['日','一','二','三','四','五','六']" class="check-label"><input type="checkbox" v-model="form.days" :value="k">周{{v}}</label></div><small class="field-note">不选星期表示每天；跨午夜归属于开始日。</small></template><div v-if="preview?.matches" class="preview-box"><h3><Eye :size="16"/>预览：命中 {{preview.matches.length}} / {{preview.total}} 个任务</h3><div v-for="p in preview.matches.slice(0,8)"><span>{{p.name}}</span><small>↑ {{format(p.upload)}} · ↓ {{format(p.download)}}</small></div><p v-if="preview.matches.length>8">另有 {{preview.matches.length-8}} 个任务</p><p v-if="!preview.matches.length">当前任务没有命中，保存后仍会对未来匹配的任务生效。</p></div></template>
        <template v-if="modal.kind==='labels'"><p class="form-intro">为选中的 {{selected.length}} 个任务替换本地标签，原生标签保持独立。</p><label>本地标签<input v-model="form.tags" placeholder="例如：保种, 纪录片"></label><small class="field-note">用逗号分隔；留空清除本地标签。规则可以同时匹配本地与原生标签。</small></template>
        <template v-if="modal.kind==='override'"><p class="form-intro">为 {{selected.length}} 个任务临时调整权重或收紧上限，到期自动恢复规则。</p><div class="form-two"><label>临时上传上限 · MiB/s<input v-model="form.upload" type="number" min="0.001" step="any" placeholder="留空不增加限制"></label><label>临时下载上限 · MiB/s<input v-model="form.download" type="number" min="0.001" step="any" placeholder="留空不增加限制"></label></div><div class="form-two"><label>临时权重<input v-model="form.weight" type="number" min="1" max="100" required></label><label>有效分钟数<input v-model="form.minutes" type="number" min="1" max="1440" required></label></div><div class="form-callout"><Zap :size="17"/>提高权重可争取更多池内份额，仍遵守池硬上限和单种规则上限。</div></template>
        <template v-if="modal.kind==='explain'&&explanation"><div class="explain-name"><Files :size="22"/><div><h3>{{explanation.name}}</h3><p>{{explanation.clientName}} · {{explanation.hosts.join(' / ')||'等待 Tracker 元数据'}}</p></div></div><div class="explain-metrics"><div><span>当前上传</span><strong>{{explanation.online?format(explanation.upload):'未知'}}</strong></div><div><span>当前下载</span><strong>{{explanation.online?format(explanation.download):'未知'}}</strong></div><div><span>主带宽池</span><strong>{{plan(explanation.key)?.managed?plan(explanation.key).poolName:'不接管'}}</strong></div></div><table class="explain-table"><thead><tr><th>控制层级</th><th>上传</th><th>下载</th></tr></thead><tbody><tr><td>规则 / 池分配目标</td><td>{{format(plan(explanation.key)?.upload)}}</td><td>{{format(plan(explanation.key)?.download)}}</td></tr><tr><td>下载器当前回读</td><td>{{format(explanation.uploadLimit)}}</td><td>{{format(explanation.downloadLimit)}}</td></tr><tr><td>最近确认写入值</td><td>{{data.managed.some(m=>m.key===explanation.key&&m.direction==='upload')?format(data.managed.find(m=>m.key===explanation.key&&m.direction==='upload').last):'尚未写入'}}</td><td>{{data.managed.some(m=>m.key===explanation.key&&m.direction==='download')?format(data.managed.find(m=>m.key===explanation.key&&m.direction==='download').last):'尚未写入'}}</td></tr></tbody></table><p class="field-note">回读更新时间 {{time(explanation.updated)}}。没有确认记录时，“最近确认写入值”不代表已执行。原生全局、替代限速和 TR 既有分组也会约束速度。</p><div v-if="data.managed.length||detail?.limitIssues?.length" class="limit-detail-list"><p v-for="m in data.managed" :key="m.direction" :class="{issue:['conflict','failed','unconfirmed','review'].includes(m.status?.state)}"><strong>{{m.direction==='upload'?'上传':'下载'}} · {{m.status?.label||'已回读确认'}}</strong><span v-if="m.status?.message">{{m.status.message}}</span></p><p v-for="m in detail?.limitIssues?.filter(v=>!data.managed.some(r=>r.direction===v.direction))" :key="m.direction" class="issue"><strong>{{m.direction==='upload'?'上传':'下载'}} · {{m.state==='conflict'?'写入前值变化':'写入或回读失败'}}</strong><span>{{m.message}}</span></p></div><div v-if="plan(explanation.key)?.execution&&!data.managed.some(m=>m.status?.state!=='confirmed')&&!detail?.limitIssues?.length" class="form-callout">最近调度：{{plan(explanation.key).execution}}</div><div class="form-section-title">命中的规则</div><div class="matched-rule" v-for="r in plan(explanation.key)?.matchedRules"><Check :size="14"/>{{r.name}}</div><p v-if="!plan(explanation.key)?.matchedRules.length" class="secondary">没有命中自动化规则。</p><ul class="reason-list"><li v-for="r in plan(explanation.key)?.reasons">{{r}}</li></ul><div v-if="!compact&&data.managed.some(m=>m.key===explanation.key&&['conflict','failed','unconfirmed','review'].includes(m.status?.state))" class="form-callout warning"><AlertTriangle :size="18"/><div>以上限速结果需要核对。重新接管将以当前实际值继续调度，并保留最初恢复基线。<button type="button" class="text-button" @click="reclaim(explanation.key)" :disabled="saving">重新接管此任务<ChevronRight :size="13"/></button></div></div><div v-if="plan(explanation.key)?.override" class="form-callout"><Clock3 :size="17"/><div>临时设置在 {{time(plan(explanation.key).override.expires)}} 到期。<button v-if="!compact" type="button" class="text-button" @click="clearOverride(explanation.key)">取消临时设置</button></div></div></template>
        <template v-if="modal.kind==='mode'"><div class="confirm-visual"><FlaskConical v-if="!demo" :size="34"/><Server v-else :size="34"/></div><p class="confirm-copy">{{demo?'切换后开始读取你已保存的真实下载器。自动接管会保持关闭，先查看分组和限速计划，再决定是否开启。':'切换后只显示独立演示任务，不连接真实下载器。'}}</p><div class="form-callout">如当前存在已接管设置，请先在设置页“释放接管并恢复”，再切换环境。</div></template>
        <template v-if="modal.kind==='control'"><div class="confirm-visual"><ShieldCheck :size="35"/></div><p class="confirm-copy">{{demo?'将在演示任务上模拟执行限速，真实下载器不会受到影响。':'将按已启用规则持续修改真实下载器的单种限速。关闭网页后，后台仍会运行。'}}</p><div class="form-callout">{{data.matchedCount}} 个任务命中规则。全局预算只覆盖受管任务；未命中的任务保留原生设置。请先在种子详情或规则预览中检查目标值。</div></template>
        <template v-if="modal.kind==='release'"><p class="confirm-copy">停止自动接管，并尝试恢复当前环境中各任务接管前的限速。</p><div class="form-callout">仅在当前值仍等于本程序最后确认写入值时恢复。失联、外部修改或写入未确认的项会保留，并显示待处理状态。</div></template>
        <template v-if="modal.kind==='delete'"><p class="confirm-copy">删除“{{modal.name}}”？</p><p class="secondary">删除规则后，相关任务将在接管运行的下一轮重新计算。删除下载器前，需要先释放接管。</p></template>
        <template v-if="modal.kind==='settings'"><p class="form-intro">预算仅覆盖命中规则或临时设置的任务。建议为网络波动保留余量。</p><div class="form-two"><label>受管上传总预算 · MiB/s<input v-model="form.uploadBudget" type="number" min="0.001" step="any" placeholder="留空不设总预算"></label><label>受管下载总预算 · MiB/s<input v-model="form.downloadBudget" type="number" min="0.001" step="any" placeholder="留空不设总预算"></label></div><div class="form-two"><label>状态同步间隔 · 秒<input v-model="form.pollSeconds" type="number" min="3" max="300" required></label><label>限速调度间隔 · 秒<input v-model="form.controlSeconds" type="number" min="10" max="600" required></label></div><label>计划时区<input v-model="form.timezone" required placeholder="Asia/Shanghai"></label><label class="check-label demand-option"><input type="checkbox" v-model="form.demandAware">按需求回收闲置额度，保留探测份额</label><small class="field-note">开启时按实测速率估计需求，持续触顶的任务逐步提额；关闭时采用固定加权分配。</small></template>
        <template v-if="modal.kind==='password'"><label>当前密码<input v-model="form.current" type="password" autocomplete="current-password" required maxlength="256"></label><label>新密码<input v-model="form.password" type="password" autocomplete="new-password" required minlength="10" maxlength="256"></label></template>
        <p v-if="modalError" class="form-error" role="alert">{{modalError}}</p>
      </div><div class="modal-footer"><button v-if="modal.kind==='client'" type="button" class="btn" @click="testClient" :disabled="saving||!form.url"><Wifi :size="15"/>测试连接</button><button v-if="modal.kind==='rule'" type="button" class="btn" @click="previewRule" :disabled="saving"><Eye :size="15"/>预览影响</button><div class="footer-spacer"></div><button type="button" class="btn" @click="modal=null" :disabled="saving">{{modal.kind==='explain'?'关闭':'取消'}}</button><button v-if="modal.kind==='release'" type="button" class="btn primary" @click="release" :disabled="saving">{{saving?'正在恢复…':'释放并恢复'}}</button><button v-else-if="modal.kind!=='explain'" class="btn" :class="modal.kind==='delete'?'danger':'primary'" :disabled="saving">{{saving?'处理中…':modal.kind==='delete'?'确认删除':modal.kind==='control'?'开启接管':modal.kind==='mode'?'确认切换':'保存设置'}}<Check v-if="!saving&&!['delete','control','mode'].includes(modal.kind)" :size="15"/></button></div>
    </form></section></div>
    <div v-if="toast" class="toast" :class="{error:toast.error}" role="status"><AlertTriangle v-if="toast.error" :size="18"/><CheckCircle2 v-else :size="18"/>{{toast.message}}</div>
  </div>
</template>
